from ute_core.exception import CoreException


class InfoModelException(CoreException):
    """Base exception of InfoModel exceptions."""


class InfoModelTimeoutException(InfoModelException):
    """InfoModelTimeoutException is raised when timeout occurs."""


class InfoModelConnectionException(InfoModelException):
    """InfoModelConnectionException is raised when connection problems appear."""


class InfoModelObjectNotFoundException(InfoModelException):
    """InfoModelObjectNotFoundException is raised when InfoModel object cannot be found."""


class InfoModelObjectDefinitionNotFoundException(InfoModelException):
    """InfoModelObjectDefinitionNotFoundException is raised when InfoModel object definition cannot be found."""


class InfoModelObjectParameterNotFoundException(InfoModelException):
    """InfoModelObjectParameterNotFoundException is raised when InfoModel object parameter not found."""


class InfoModelDumpNotFoundException(InfoModelException):
    """InfoModelDumpNotFoundException is raised when InfoModel objects cannot be found."""


class InfoModelQueryException(InfoModelException):
    """InfoModelQueryException base exception for query model."""


class InfoModelExpressionSyntaxException(InfoModelQueryException):
    """InfoModelExpressionSyntaxException is raised when query expression has syntax errors."""


class InfoModelQueryTimeoutException(InfoModelQueryException):
    """InfoModelQueryTimeoutException is raised when a query does not pass with a positive result before timeout."""


class InfoModelQueryParallelExecutionException(InfoModelQueryException):
    """InfoModelQueryParallelExecutionException is raised when parallel execution of queries fails."""


class InfoModelIms2ValidationException(InfoModelException):
    """InfoModelIms2ValidationException is raised when IMS2 validation does not pass with a positive result."""


class InfoModelIms2ReaderException(InfoModelException):
    """InfoModelIms2ReaderException is raised when IMS2 reader errors occurs."""


class InfoModelIms2ReaderDefinitionException(InfoModelException):
    """InfoModelIms2ReaderException is raised when IMS2 reader errors occurs."""
